"use client";
import React from "react";
import { motion } from "framer-motion";

type Direction = "up" | "down" | "left" | "right" | "none";

export interface RevealProps {
  children: React.ReactNode;
  delay?: number;
  duration?: number;
  className?: string;
  direction?: Direction;
  distance?: number;
  type?: "fade" | "slide" | "zoom";
  once?: boolean;
}

export default function Reveal({
  children,
  delay = 0,
  duration = 0.6,
  className,
  direction = "up",
  distance = 24,
  type = "fade",
  once = true,
}: RevealProps) {
  const offset =
    direction === "up"
      ? { x: 0, y: distance }
      : direction === "down"
        ? { x: 0, y: -distance }
        : direction === "left"
          ? { x: distance, y: 0 }
          : direction === "right"
            ? { x: -distance, y: 0 }
            : { x: 0, y: 0 };

  const initial =
    type === "slide"
      ? { opacity: 0, ...offset }
      : type === "zoom"
        ? { opacity: 0, scale: 0.95 }
        : { opacity: 0 };

  return (
    <motion.div
      initial={initial}
      whileInView={{ opacity: 1, x: 0, y: 0, scale: 1 }}
      viewport={{ once, amount: 0.15 }}
      transition={{ delay, duration, ease: [0.22, 1, 0.36, 1] }}
      className={className}
      data-testid="rendered-component-reveal"
    >
      {children}
    </motion.div>
  );
}

